        let listLength = (this.selectedList.length - this.byePlayers.length);
        if (this.teamSize == 5) {
            if ((listLength / 10) % 1 == 0) {
                this.teamCount = (Math.floor(listLength / 10) * 2);
            }
            else {

                this.teamCount = (Math.floor(listLength / 10) * 2) + 2;

            }
        }
        else if (this.teamSize == 4) {
