                this.teamCount = (Math.floor(listLength / 8) * 2);
            }
            else {

                this.teamCount = (Math.floor(listLength / 8) * 2) + 2;

            }
        }
        else if (this.teamSize == 3) {
            if ((listLength / 6) % 1 == 0) {
                this.teamCount = (Math.floor(listLength / 6) * 2);
            }
            else {

                this.teamCount = (Math.floor(listLength / 6) * 2) + 2;

